INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('projet-zero', 1, 'Projet Zero', 6, NULL, '/images/projects/ProjetZero_cover.webp', '/images/projects/ProjetZero_reveal.webp', 'projet-zero-pillar', '{"de": "Projet Zero ist ein Sci-Fi-RPG-Server für Minecraft: Sie sind ein menschlicher Soldat-Astronaut und halten die Stellung gegen eine außerirdische Zivilisation, deren Technologie unsere weit übertrifft, gespeist aus einer seltsamen, uralten blauen Energie.", "en": "Projet Zero is a sci-fi RPG Minecraft server: you''re a human soldier-astronaut holding the line against an alien civilisation whose technology dwarfs ours, all of it drawn from a strange ancient blue energy.", "es": "Projet Zero es un servidor de Minecraft RPG de ciencia ficción: eres un soldado-astronauta humano que resiste frente a una civilización alienígena cuya tecnología supera con creces la nuestra, toda ella nacida de una extraña energía azul ancestral.", "fr": "Projet Zero est un serveur Minecraft RPG de science-fiction : vous incarnez un soldat-astronaute humain qui tient la ligne face à une civilisation extraterrestre dont la technologie écrase la nôtre, entièrement puisée dans une étrange énergie bleue ancestrale."}', '{"de": "Projet Zero: Marke und Showcase-Website für einen Sci-Fi-RPG-Server in Minecraft, von Facile Studio. Eine Soldat-Astronaut-Identität rund um eine einzige uralte blaue Energie, bis in Shop und Battle Pass getragen. Entwickelt mit Next.js, React und TypeScript.", "en": "Projet Zero is a sci-fi RPG Minecraft server brand and showcase website by Facile Studio — a soldier-astronaut identity built around a single ancient blue energy, carried through the shop and battle-pass pages. Built with Next.js, React and TypeScript.", "es": "Projet Zero: marca y web de presentación de un servidor de Minecraft RPG de ciencia ficción, por Facile Studio. Una identidad de soldado-astronauta construida en torno a una única energía azul ancestral, llevada hasta la tienda y el pase de batalla. Desarrollado con Next.js, React y TypeScript.", "fr": "Projet Zero : identité et site vitrine d''un serveur Minecraft RPG de science-fiction, par Facile Studio. Une identité de soldat-astronaute bâtie autour d''une seule énergie bleue ancestrale, déclinée jusqu''à la boutique et au battle pass. Développé avec Next.js, React et TypeScript."}', '{"de": "Mit einer Farbe und einem Zeichen spürbar machen, dass eine außerirdische Zivilisation uns Jahrtausende voraus ist, und das bis zum Shop und zum Battle Pass tragen, ohne in generisches Gamer-Blau abzurutschen.", "en": "Make an alien civilisation feel millennia ahead of us through one colour and one mark, then carry that all the way to a shop and battle-pass page without it curdling into generic gamer-blue.", "es": "Hacer que una civilización alienígena parezca ir milenios por delante con un solo color y una sola marca, y llevarlo hasta la tienda y el pase de batalla sin caer en el típico azul gamer.", "fr": "Faire sentir qu''une civilisation extraterrestre a des millénaires d''avance avec une seule couleur et un seul logo, puis porter ça jusqu''à la boutique et au battle pass sans virer au bleu gamer générique."}', '{brandIdentity,productDesign,webDevelopment}', '{Figma,Photoshop,Illustrator}', '2026', '{https://picsum.photos/seed/projet-zero-sketches/1400/1000,https://picsum.photos/seed/projet-zero-logo-a/1200/1200,https://picsum.photos/seed/projet-zero-logo-b/1200/1200,https://picsum.photos/seed/projet-zero-logo-c/1200/1200,https://picsum.photos/seed/projet-zero-moodboard/1500/1000,https://picsum.photos/seed/projet-zero-instagram/1200/1500,https://picsum.photos/seed/projet-zero-web-preview/1500/1000,https://picsum.photos/seed/projet-zero-web-home/1700/1100,https://picsum.photos/seed/projet-zero-web-shop/1700/1100,https://picsum.photos/seed/projet-zero-web-chapter/1700/1100,https://picsum.photos/seed/projet-zero-web-mobile/1200/1600,https://picsum.photos/seed/projet-zero-web-glow/1700/1000,https://picsum.photos/seed/projet-zero-logo-d/1200/1200,https://picsum.photos/seed/projet-zero-logo-e/1200/1200,https://picsum.photos/seed/projet-zero-sketches-2/1400/1000,https://picsum.photos/seed/projet-zero-moodboard-2/1500/1000}', '{"{\"de\": \"Das Logo musste zugleich als uraltes Artefakt und als UI-Zeichen funktionieren. Deshalb wurde jede Iteration erst winzig, in Favicon-Größe, getestet und dann groß.\", \"en\": \"The logo had to read as an ancient artifact and a UI mark at the same time, so every iteration was tested small — favicon-small — before it was tested big.\", \"es\": \"El logo tenía que leerse a la vez como artefacto antiguo y como icono de interfaz, así que cada iteración se probó en pequeño, tamaño favicon, antes de probarla en grande.\", \"fr\": \"Le logo devait se lire à la fois comme un artefact ancien et comme un signe d''interface. Chaque itération a donc été testée en tout petit, taille favicon, avant d''être testée en grand.\"}","{\"de\": \"Blau trägt die gesamte Lore: Es ist die außerirdische Energiequelle. Darum greifen jedes Leuchten, jede Seltenheitsstufe und jede Kapitelbelohnung bewusst auf dieselbe Handvoll Blautöne zurück.\", \"en\": \"Blue carries the entire lore: it''s the alien energy source, so every glow, every rarity tier and every chapter reward reuses the same handful of blues on purpose.\", \"es\": \"El azul sostiene todo el lore: es la fuente de energía alienígena, así que cada brillo, cada nivel de rareza y cada recompensa de capítulo reutiliza a propósito el mismo puñado de azules.\", \"fr\": \"Le bleu porte tout le lore : c''est la source d''énergie extraterrestre, donc chaque lueur, chaque niveau de rareté et chaque récompense de chapitre reprend volontairement la même poignée de bleus.\"}"}', '2026-09-28 15:54:56.792', '2026-09-29 10:31:50.548', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('marcel', 0, 'Marcel', 12, 'https://marcel.my/', '/images/projects/Marcel_cover.webp', NULL, 'marcel', '{"de": "Marcel ist eine App, die Ihr Leben in ein Spiel verwandelt und Aufgaben und Gewohnheiten zu Abenteuern macht.", "en": "Marcel is an application that lets you turn your life into a game by transforming tasks and habits into adventures.", "es": "Marcel es una aplicación que convierte tu vida en un juego, transformando tus tareas y hábitos en aventuras.", "fr": "Marcel est une application qui transforme votre vie en jeu, en changeant vos tâches et vos habitudes en aventures."}', '{"de": "Marcel ist eine Wellbeing-App von Facile Studio. Spielerisches Gewohnheitstracking und Aufgabenverwaltung, entwickelt mit Svelte und Go.", "en": "Marcel is a wellbeing application by Facile Studio. Gamified habit tracking and task management, built with Svelte and Go.", "es": "Marcel es una aplicación de bienestar de Facile Studio. Seguimiento de hábitos y gestión de tareas gamificados, desarrollados con Svelte y Go.", "fr": "Marcel est une application de bien-être signée Facile Studio. Suivi d''habitudes et gestion de tâches gamifiés, développés avec Svelte et Go."}', '{"de": "Eine To-do-Liste in etwas verwandeln, das man wirklich öffnen will: Gewohnheiten, Serien und überfällige Aufgaben sollten sich wie eine Quest anfühlen, nicht wie eine Pflicht.", "en": "Turn a to-do list into something people actually want to open — habits, streaks and overdue tasks had to feel like a quest, not a chore.", "es": "Convertir una lista de tareas en algo que de verdad quieras abrir: hábitos, rachas y tareas atrasadas tenían que sentirse como una misión, no como una obligación.", "fr": "Faire d''une to-do list un truc qu''on a vraiment envie d''ouvrir : habitudes, séries et tâches en retard devaient ressembler à une quête, pas à une corvée."}', '{transformation,redesign,appDevelopment}', '{Svelte,Go,Postgres,Figma}', '2025', '{/images/projects/Marcel%202x2%20logo.png,/images/projects/Marcel%202x3%20rebranding.png,/images/projects/Marcel%203x3%20dashboard.webp,/images/projects/Marcel_1x2_phone.webp,/images/projects/Marcel_2x1_onboarding.webp,/images/projects/Marcel_1x1_calendar_dark.webp,/images/projects/Marcel_2x2_calendar.webp,/images/projects/Marcel_1x1_red.webp,/images/projects/Marcel_1x1_orange.webp,/images/projects/Marcel_1x1_yellow.webp,/images/projects/Marcel_1x1_green.webp,/images/projects/Marcel_1x1_blue.webp,/images/projects/Marcel_1x1_purple.webp,/images/projects/Marcel_2x2_dev.webp}', '{"{\"de\": \"Die Belohnungsschleife war das eigentliche Designproblem: Gold und Erfahrung mussten in dem Moment ankommen, in dem eine Aufgabe abgehakt wird, sonst fällt das Spiel auseinander.\", \"en\": \"The reward loop was the whole design problem: gold and experience had to land the moment a task is checked, or the game falls apart.\", \"es\": \"Todo el reto de diseño era el ciclo de recompensas: el oro y la experiencia tenían que llegar en cuanto marcas una tarea, o el juego se viene abajo.\", \"fr\": \"Toute la difficulté tenait dans la boucle de récompense : l''or et l''expérience devaient tomber à l''instant où une tâche est cochée, sinon le jeu s''effondre.\"}","{\"de\": \"Alles wurde in Figma gezeichnet, bevor auch nur eine Komponente geschrieben war. So blieb der Svelte-Build eine Übersetzungsarbeit statt einer Entdeckungsreise.\", \"en\": \"Everything was drawn in Figma before a single component was written, so the Svelte build stayed a translation job rather than a discovery one.\", \"es\": \"Todo se dibujó en Figma antes de escribir un solo componente, así que el desarrollo en Svelte fue un trabajo de traducción, no de descubrimiento.\", \"fr\": \"Tout a été dessiné dans Figma avant d''écrire le moindre composant, si bien que le développement Svelte est resté un travail de traduction, pas d''exploration.\"}"}', '2026-09-28 15:54:56.725', '2026-09-28 17:24:45.577', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('hottake', 3, 'Hottake', 1, 'https://www.instagram.com/p/DL5Fr7dol_5/?img_index=1', '/images/projects/Hottake.webp', '/videos/Hottake.webp', NULL, '{"de": "Hottake ist eine Community-Plattform, noch in Entwicklung, auf der Sie Ihren Musikgeschmack ranken. Wir haben einen klaren, kuratierten und modernen Look entwickelt, der jeden Musikfan anspricht.", "en": "Hottake is a community-driven platform to rank your music taste that is under development. We came up with a straightforward, curated and modern look that would attract any kind of music enjoyer.", "es": "Hottake es una plataforma comunitaria, aún en desarrollo, para clasificar tus gustos musicales. Creamos un look directo, cuidado y moderno, pensado para atraer a cualquier amante de la música.", "fr": "Hottake est une plateforme communautaire, encore en développement, pour classer vos goûts musicaux. Nous avons imaginé un look direct, soigné et moderne, fait pour séduire tous les amateurs de musique."}', '{"de": "Hottake ist eine Community-Plattform zum Ranken des Musikgeschmacks von Facile Studio, mit kuratiertem, modernem Look für Musikbegeisterte. Entwickelt mit Next.js, React und GSAP.", "en": "Hottake is a community-driven music taste ranking platform by Facile Studio, with a curated, modern look built for music enthusiasts. Built with Next.js, React and GSAP.", "es": "Hottake es una plataforma comunitaria para clasificar gustos musicales, de Facile Studio, con un look cuidado y moderno pensado para los amantes de la música. Desarrollada con Next.js, React y GSAP.", "fr": "Hottake est une plateforme communautaire de classement des goûts musicaux, signée Facile Studio, au look soigné et moderne pensé pour les passionnés de musique. Développée avec Next.js, React et GSAP."}', '{"de": "Das Ranking des eigenen Musikgeschmacks so kuratiert und modern wirken lassen, dass jeder darüber öffentlich streiten will.", "en": "Make ranking your music taste feel curated and modern enough that any listener wants to argue about it publicly.", "es": "Que clasificar tus gustos musicales se sienta tan cuidado y moderno que cualquier oyente quiera discutirlo en público.", "fr": "Rendre le classement de vos goûts musicaux assez soigné et moderne pour que chaque auditeur ait envie d''en débattre publiquement."}', '{productDesign,webDevelopment,motionDesign}', '{TS,Next.js,React,GSAP}', '2025', '{/images/projects/HottakeShow.webp,https://media.w3.org/2010/05/video/movie_300.mp4,https://picsum.photos/seed/hottake-b/1300/1600,https://picsum.photos/seed/hottake-x0/1500/1000}', '{"{\"de\": \"Die Ranking-Interaktion musste tausend Taps überstehen: Jeder Zustand wurde als Prototyp gebaut, bevor er gestaltet wurde.\", \"en\": \"The ranking interaction had to survive a thousand taps — every state was prototyped before it was styled.\", \"es\": \"La interacción de ranking tenía que aguantar mil toques: cada estado se prototipó antes de darle estilo.\", \"fr\": \"L''interaction de classement devait survivre à mille tapotements : chaque état a été prototypé avant d''être habillé.\"}","{\"de\": \"Schrift und Körnung übernehmen das Branding, damit die Oberfläche selbst fast unsichtbar bleiben kann.\", \"en\": \"Type and grain do the branding work, so the interface itself can stay almost invisible.\", \"es\": \"La tipografía y el grano hacen el trabajo de marca, así la interfaz puede quedar casi invisible.\", \"fr\": \"La typo et le grain font le travail de marque, pour que l''interface elle-même reste presque invisible.\"}"}', '2026-09-28 15:55:20.341', '2026-09-28 15:56:43.013', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('evelynecrea', 4, 'EvelyneCrea', 8, 'https://www.evelynecrea.com', '/images/projects/Green.webp', '/videos/EvelyneCrea_web.mp4', NULL, '{"de": "Eine warme, handgemachte Portfolio-Website, die die Kreationen in den Mittelpunkt stellt und alles andere aus dem Weg räumt.", "en": "A warm, handcrafted portfolio site that puts the creations centre stage and keeps everything else out of the way.", "es": "Un portfolio cálido y artesanal que pone las creaciones en primer plano y aparta todo lo demás.", "fr": "Un portfolio chaleureux et fait main, qui place les créations au premier plan et écarte tout le reste."}', '{"de": "Portfolio-Redesign von Facile Studio für eine Kreativschaffende. Individuelle visuelle Identität, Animationen und ein organischer Navigationsfluss.", "en": "Portfolio redesign by Facile Studio for a creative professional. Custom visual identity, animations, and organic navigation flow.", "es": "Rediseño de portfolio de Facile Studio para una profesional creativa. Identidad visual a medida, animaciones y una navegación orgánica.", "fr": "Refonte de portfolio par Facile Studio pour une professionnelle de la création. Identité visuelle sur mesure, animations et navigation organique."}', '{"de": "Handgemachte Kreationen in den Mittelpunkt stellen und jedes Stück Oberfläche aus ihrem Weg halten.", "en": "Put handmade creations centre stage and keep every piece of interface out of their way.", "es": "Poner creaciones hechas a mano en primer plano y que ningún elemento de la interfaz se interponga.", "fr": "Mettre des créations faites main au premier plan et ne laisser aucun élément d''interface leur faire de l''ombre."}', '{artDirection,webDevelopment,motionDesign}', '{TS,Next.js,React,GSAP}', '2024', '{/images/projects/EvelyneCrea.webp,https://picsum.photos/seed/evelyne-b/1200/1500,https://media.w3.org/2010/05/bunny/movie.mp4,https://picsum.photos/seed/evelyne-c/1700/1000}', '{"{\"de\": \"Die Wärme kommt von der Palette und dem Tempo, nicht von Dekoration: Das Layout bleibt bewusst fast leer.\", \"en\": \"Warmth came from the palette and the pacing, not from decoration — the layout stays almost bare on purpose.\", \"es\": \"La calidez viene de la paleta y del ritmo, no de la decoración: la maquetación se queda casi desnuda a propósito.\", \"fr\": \"La chaleur vient de la palette et du rythme, pas de la décoration : la mise en page reste volontairement presque nue.\"}"}', '2026-09-28 15:55:20.36', '2026-09-28 15:56:43.025', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('benky', 7, 'Benky', 1, 'https://benky.space', '/images/projects/Benky_cover.webp', NULL, NULL, '{"de": "Benky ist eine Lern-App: Kursnotizen hochladen, der KI Fragen dazu stellen und das Gelernte in Karteikarten, Quiz und einen Lernplan verwandeln.", "en": "Benky is a study app: bring your course notes, ask AI questions about them, and turn what you learn into flashcards, quizzes and a study plan.", "es": "Benky es una app de estudio: subes tus apuntes, le haces preguntas a la IA y conviertes lo que aprendes en flashcards, cuestionarios y un plan de estudio.", "fr": "Benky est une application de révision : on y dépose ses notes de cours, on pose des questions à l''IA, et on transforme ce qu''on apprend en flashcards, quiz et planning de révision."}', '{"de": "Benky ist eine Lern-App von Facile Studio. Kursmaterial, KI-Erklärungen, Karteikarten, Quiz und Lernplanung an einem Ort, im Web und auf dem Mac.", "en": "Benky is a study app by Facile Studio. Course materials, AI explanations, flashcards, quizzes and study planning in one place, on the web and on Mac.", "es": "Benky es una app de estudio de Facile Studio. Materiales, explicaciones con IA, flashcards, cuestionarios y planificación en un solo lugar, en la web y en Mac.", "fr": "Benky est une application de révision signée Facile Studio. Supports de cours, explications par IA, flashcards, quiz et planning réunis au même endroit, sur le web et sur Mac."}', '{"de": "Die verstreuten Tabs einer Lernsession durch einen Ort ersetzen, an dem Material, Fragen, Notizen und Übung aufeinander folgen.", "en": "Replace the scattered tabs of a study session with one place where materials, questions, notes and practice follow each other.", "es": "Sustituir las pestañas dispersas de una sesión de estudio por un único lugar donde materiales, preguntas, notas y práctica se suceden.", "fr": "Remplacer les onglets éparpillés d''une session de révision par un seul endroit où supports, questions, notes et entraînement s''enchaînent."}', '{appDevelopment,desktopDevelopment}', '{}', '2026', '{/images/projects/Benky_0.webp,/images/projects/Benky_1.webp,/images/projects/Benky_2.webp,/images/projects/Benky_3.webp,/images/projects/Benky_4.webp}', '{"{\"de\": \"Jede Antwort verweist auf dein eigenes Material, so wird aus einer Nachfrage eine Notiz und daraus eine Karteikarte.\", \"en\": \"Every answer points back to your own materials, so a follow-up question turns into a note and then into a flashcard.\", \"es\": \"Cada respuesta remite a tus propios materiales, así que una pregunta de seguimiento se convierte en una nota y después en una flashcard.\", \"fr\": \"Chaque réponse renvoie à vos propres supports : une question de suivi devient une note, puis une flashcard.\"}"}', '2026-09-28 15:55:20.423', '2026-09-29 12:10:52.778', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('muse', 9, 'Muse', 6, 'https://github.com/FacileStudio', '/images/projects/Muse.webp', NULL, NULL, '{"de": "Die Web-Komponentenbibliothek hinter der Suite: ein einziger Satz aus Svelte-Komponenten, Tokens und Bewegungsregeln, aus dem jedes Tool des Studios gebaut ist.", "en": "The web component library behind the Suite: one set of Svelte components, tokens and motion rules that every studio tool is built from.", "es": "La librería de componentes web detrás de la Suite: un único conjunto de componentes Svelte, tokens y reglas de movimiento con el que se construye cada herramienta del estudio.", "fr": "La bibliothèque de composants web derrière la Suite : un seul jeu de composants Svelte, de tokens et de règles d''animation, sur lequel repose chaque outil du studio."}', '{"de": "Muse ist die Svelte-Komponentenbibliothek von Facile Studio hinter der Facile Suite: gemeinsame Komponenten, Design-Tokens und Bewegungsregeln für jedes Tool.", "en": "Muse is the Svelte component library by Facile Studio behind the Facile Suite: shared components, design tokens and motion rules for every tool.", "es": "Muse es la librería de componentes Svelte de Facile Studio detrás de la Facile Suite: componentes compartidos, design tokens y reglas de movimiento para cada herramienta.", "fr": "Muse est la bibliothèque de composants Svelte de Facile Studio derrière la Facile Suite : composants partagés, design tokens et règles d''animation pour chaque outil."}', '{"de": "Fünfzehn Tools, die wie ein Produkt aussehen sollten, ohne dass fünfzehn Teams denselben Button neu erfinden.", "en": "Fifteen tools that had to look like one product without fifteen teams re-solving the same button.", "es": "Quince herramientas que tenían que parecer un solo producto, sin quince equipos resolviendo otra vez el mismo botón.", "fr": "Quinze outils qui devaient ressembler à un seul produit, sans quinze équipes pour réinventer le même bouton."}', '{designSystem,frontendDevelopment}', '{Svelte,TS,Tailwind,Vite}', '2026', '{https://picsum.photos/seed/muse-a/1800/1000,https://picsum.photos/seed/muse-b/1400/1500,https://picsum.photos/seed/muse-c/1500/1000}', '{"{\"de\": \"Eine gemeinsame Bibliothek lohnt sich nur, wenn sie schneller ist, als die Komponente neu zu schreiben. Deshalb kam die API vor dem Styling.\", \"en\": \"A shared library only pays off if using it is faster than writing the component again, so the API came before the styling.\", \"es\": \"Una librería compartida solo compensa si usarla es más rápido que volver a escribir el componente, así que la API fue antes que el estilo.\", \"fr\": \"Une bibliothèque partagée n''est rentable que si l''utiliser va plus vite que réécrire le composant : l''API est donc passée avant le style.\"}"}', '2026-09-28 15:55:20.464', '2026-09-28 15:56:43.102', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('laura-herve', 2, 'LauraHerve', 4, 'https://lauraherve.com', '/images/projects/Laura.webp', '/videos/LauraHerve.mp4', NULL, '{"de": "Eine Showcase-Website für die Künstlerin, getragen von fließender Bewegung und einem kühnen redaktionellen Layout, das den Werken Raum lässt.", "en": "A showcase site for the artist, driven by smooth motion and a bold editorial layout that lets the work breathe.", "es": "Una web de presentación para la artista, con animaciones fluidas y una maquetación editorial atrevida que deja respirar la obra.", "fr": "Un site vitrine pour l''artiste, porté par des animations fluides et une mise en page éditoriale audacieuse qui laisse respirer les œuvres."}', '{"de": "Künstlerportfolio, gestaltet und entwickelt von Facile Studio. Typografiezentriertes Design mit fließenden Übergängen und responsiven Layouts.", "en": "Artist portfolio designed and built by Facile Studio. Typography-focused design with smooth transitions and responsive layouts.", "es": "Portfolio de artista diseñado y desarrollado por Facile Studio. Un diseño centrado en la tipografía, con transiciones fluidas y maquetaciones adaptables.", "fr": "Portfolio d''artiste conçu et développé par Facile Studio. Un design centré sur la typographie, avec des transitions fluides et des mises en page responsives."}', '{"de": "Einem Werk auf dem Bildschirm Raum geben, ohne dass die Website ihm je die Aufmerksamkeit stiehlt.", "en": "Give a body of work room to breathe on screen without the site ever pulling attention away from it.", "es": "Dar espacio a una obra en pantalla sin que la web le robe nunca el protagonismo.", "fr": "Laisser respirer une œuvre à l''écran sans que le site ne lui vole jamais la vedette."}', '{artDirection,webDevelopment,motionDesign}', '{TS,Svelte,GSAP}', '2024', '{/images/projects/LauraHerve.webp,https://picsum.photos/seed/laura-b/1400/1500,https://media.w3.org/2010/05/bunny/trailer.mp4,https://picsum.photos/seed/laura-herve-x0/1500/1000}', '{"{\"de\": \"Hier trägt die Bewegung den gesamten redaktionellen Rhythmus: Nichts bewegt sich, ohne sich den Blick des Betrachters zu verdienen.\", \"en\": \"Motion carries the whole editorial rhythm here — nothing moves unless it earns the reader''s eye.\", \"es\": \"Aquí el movimiento marca todo el ritmo editorial: nada se mueve si no merece la mirada de quien lee.\", \"fr\": \"Ici, le mouvement porte tout le rythme éditorial : rien ne bouge sans mériter le regard du lecteur.\"}"}', '2026-09-28 15:55:20.318', '2026-09-28 15:56:42.998', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('vidoq', 6, 'Vidoq', 1, 'https://vidoq.fr', '/images/projects/Vidoq_cover.webp', NULL, NULL, '{"de": "Vidoq ist eine Plattform zur Prüfung des digitalen Fußabdrucks: Suche nach E-Mail, Telefonnummer, Benutzername, Name, IP oder Adresse und sieh, wo sie in öffentlichen Daten und bekannten Datenlecks auftauchen.", "en": "Vidoq is a platform for auditing your digital footprint: search an email, phone, username, name, IP or address and see where it shows up in public data and known breaches.", "es": "Vidoq es una plataforma para auditar tu huella digital: busca un correo, un teléfono, un usuario, un nombre, una IP o una dirección y descubre dónde aparece en datos públicos y filtraciones conocidas.", "fr": "Vidoq est une plateforme d''audit d''empreinte numérique : cherchez un e-mail, un téléphone, un pseudo, un nom, une IP ou une adresse et voyez où ils apparaissent dans les données publiques et les fuites connues."}', '{"de": "Vidoq ist eine Plattform zur Prüfung des digitalen Fußabdrucks von Facile Studio: Suche in über 1 Mrd. indexierten Leak-Datensätzen, OSINT-Recherche, Leak-Graphen und passive Benachrichtigungen.", "en": "Vidoq is a digital footprint auditing platform by Facile Studio: breach search over 1B+ indexed records, OSINT investigation, breach graphs and passive alerting.", "es": "Vidoq es una plataforma de auditoría de huella digital de Facile Studio: búsqueda en más de mil millones de registros filtrados, investigación OSINT, grafos de filtraciones y alertas pasivas.", "fr": "Vidoq est une plateforme d''audit d''empreinte numérique signée Facile Studio : recherche dans plus d''un milliard d''enregistrements de fuites, investigation OSINT, graphes de fuites et alertes passives."}', '{"de": "Über eine Milliarde Leak-Datensätze nach exaktem Wert, Platzhalter oder mehreren Feldern zugleich durchsuchen, und die Antwort trotzdem so schnell liefern, dass sie sofort wirkt.", "en": "Search more than a billion breach records by exact value, wildcard or several fields at once, and keep the answer fast enough to feel instant.", "es": "Buscar en más de mil millones de registros filtrados por valor exacto, comodín o varios campos a la vez, con una respuesta tan rápida que parezca instantánea.", "fr": "Chercher dans plus d''un milliard d''enregistrements de fuites par valeur exacte, joker ou plusieurs champs à la fois, avec une réponse assez rapide pour sembler instantanée."}', '{appDevelopment,webDevelopment}', '{}', '2026', '{/images/projects/Vidoq_0.webp,/images/projects/Vidoq_1.webp,/images/projects/Vidoq_2.webp,/images/projects/Vidoq_3.webp,/images/projects/Vidoq_4.webp}', '{"{\"de\": \"Überwachte Felder werden täglich mit jeder neuen Leak-Version abgeglichen, und neue Datensätze bleiben gesperrt, bis der Nutzer sie freischaltet.\", \"en\": \"Monitored fields are checked against every new breach version daily, and new records stay locked until the user chooses to unlock them.\", \"es\": \"Los campos vigilados se comparan cada día con cada nueva versión de las filtraciones, y los registros nuevos quedan bloqueados hasta que el usuario decide desbloquearlos.\", \"fr\": \"Les champs surveillés sont comparés chaque jour à chaque nouvelle version des fuites, et les nouveaux enregistrements restent verrouillés jusqu''à ce que l''utilisateur choisisse de les débloquer.\"}"}', '2026-09-28 15:55:20.406', '2026-09-28 15:56:43.065', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('solais-intra', 8, 'SolaïsIntra', 8, 'https://solais.fr/', '/images/projects/SolaïsIntra.webp', NULL, NULL, '{"de": "Ein internes Tool, das den Alltag des Solaïs-Teams vereinfacht, vom Tracking bis zum Reporting.", "en": "An internal tool that streamlines the day-to-day for the Solaïs team, from tracking to reporting.", "es": "Una herramienta interna que agiliza el día a día del equipo de Solaïs, del seguimiento a los informes.", "fr": "Un outil interne qui simplifie le quotidien de l''équipe Solaïs, du suivi jusqu''au reporting."}', '{"de": "Maßgeschneiderte Intranet-Anwendung von Facile Studio für Solaïs. Eine Plattform mit Vue.js und TypeScript für Teamarbeit und Dokumentenverwaltung.", "en": "Custom intranet application built by Facile Studio for Solaïs. Vue.js and TypeScript platform for team collaboration and document management.", "es": "Aplicación de intranet a medida desarrollada por Facile Studio para Solaïs. Una plataforma en Vue.js y TypeScript para la colaboración en equipo y la gestión documental.", "fr": "Application intranet sur mesure développée par Facile Studio pour Solaïs. Une plateforme Vue.js et TypeScript pour la collaboration d''équipe et la gestion documentaire."}', '{"de": "Tägliches Tracking und Reporting eines Teams in ein Tool packen, das man einmal öffnet und mit dem man nie kämpft.", "en": "Compress a team''s daily tracking and reporting into a tool they open once and never fight.", "es": "Condensar el seguimiento y los informes diarios de un equipo en una herramienta que se abre una vez y con la que nunca hay que pelearse.", "fr": "Condenser le suivi et le reporting quotidiens d''une équipe dans un outil qu''on ouvre une fois et contre lequel on ne se bat jamais."}', '{productDesign,webDevelopment}', '{TS,Vue.js}', '2024', '{https://picsum.photos/seed/solais-a/1800/1100,https://media.w3.org/2010/05/bunny/trailer.mp4,https://picsum.photos/seed/solais-intra-x0/1500/1000,https://media.w3.org/2010/05/bunny/trailer.mp4,https://picsum.photos/seed/solais-intra-x2/1500/1400}', '{"{\"de\": \"Interne Tools werden bei der zehnten Nutzung beurteilt, nicht bei der ersten: Dichte und Tastatur-Flow schlagen jeden Onboarding-Screen.\", \"en\": \"Internal tools get judged on the tenth use, not the first — density and keyboard flow beat any onboarding screen.\", \"es\": \"Una herramienta interna se juzga en el décimo uso, no en el primero: la densidad y el flujo con teclado ganan a cualquier pantalla de bienvenida.\", \"fr\": \"Un outil interne se juge à la dixième utilisation, pas à la première : la densité et la fluidité au clavier valent mieux que n''importe quel écran d''accueil.\"}"}', '2026-09-28 15:55:20.442', '2026-09-28 15:56:43.089', '[]');
INSERT INTO "Project" (slug, "position", name, weeks, link, image, video, "coverEffect", description, "metaDescription", challenge, services, "techStack", date, gallery, notes, "createdAt", "updatedAt", bucket) VALUES ('handvision', 5, 'HandVision', 68, 'https://hand-vision.fr', '/images/projects/uploads/1790621855668-handvision-starter.png', NULL, NULL, '{"de": "HandVision ist eine App zur Videoanalyse im Handball: Man lädt ein Spiel hoch, die KI findet jedes Tor, schneidet die Clips und macht aus dem Spielbericht Statistiken, die das ganze Team lesen kann.", "en": "HandVision is a handball video analysis app: upload a match, the AI finds every goal, cuts the clips and turns the match sheet into statistics the whole team can read.", "es": "HandVision es una aplicación de análisis de vídeo de balonmano: subes un partido, la IA encuentra cada gol, corta los clips y convierte el acta del partido en estadísticas que todo el equipo puede leer.", "fr": "HandVision est une application d''analyse vidéo pour le handball : on envoie un match, l''IA trouve chaque but, découpe les clips et transforme la feuille de match en statistiques lisibles par toute l''équipe."}', '{"de": "HandVision ist eine App zur Videoanalyse im Handball. Branding, Webdesign und Frontend von Facile Studio, entwickelt mit SvelteKit, shadcn-svelte und GSAP.", "en": "HandVision is a handball video analysis app. Branding, web design and frontend by Facile Studio, built with SvelteKit, shadcn-svelte and GSAP.", "es": "HandVision es una aplicación de análisis de vídeo de balonmano. Identidad, diseño web y frontend de Facile Studio, desarrollados con SvelteKit, shadcn-svelte y GSAP.", "fr": "HandVision est une application d''analyse vidéo pour le handball. Identité, web design et frontend par Facile Studio, développés avec SvelteKit, shadcn-svelte et GSAP."}', '{"de": "Ein KI-Analysetool so einfach machen wie das Hochladen eines Videos: Trainer sollen ohne Anleitung von der Spielaufnahme zu Clips und Zahlen kommen.", "en": "Make an AI analysis tool feel as simple as uploading a video: coaches should go from a match recording to clips and numbers without reading a manual.", "es": "Hacer que una herramienta de análisis con IA sea tan sencilla como subir un vídeo: un entrenador debe pasar de la grabación del partido a los clips y los números sin leer ningún manual.", "fr": "Rendre un outil d''analyse par IA aussi simple que l''envoi d''une vidéo : un coach doit passer de l''enregistrement du match aux clips et aux chiffres sans lire de mode d''emploi."}', '{brandIdentity,uiUxDesign,appDevelopment,transformation}', '{GSAP,Figma,Svelte,TS}', '2026', '{/images/projects/HandVision_0.webp,/images/projects/HandVision_1.webp,/images/projects/HandVision_2.webp,/images/projects/HandVision_3.webp,/images/projects/HandVision_4.webp,/images/projects/HandVision_5.webp,/images/projects/HandVision_6.webp,/images/projects/HandVision_7.webp,/images/projects/HandVision_8.webp,/images/projects/HandVision_9.webp,/images/projects/HandVision_10.webp,/images/projects/HandVision_11.webp,/images/projects/HandVision_12.webp,/images/projects/HandVision_13.webp,/images/projects/HandVision_14.webp,/images/projects/HandVision_15.webp}', '{"{\"de\": \"Eine Person hat die gesamte Oberfläche des Produkts getragen: Logo, Schrift, Farben, jeder Screen in Figma und danach der SvelteKit-Build.\", \"en\": \"One person carried the whole front of the product: logo, font, colours, every screen in Figma, then the SvelteKit build.\", \"es\": \"Una sola persona llevó toda la cara visible del producto: logo, tipografía, colores, cada pantalla en Figma y después el desarrollo en SvelteKit.\", \"fr\": \"Une seule personne a porté toute la façade du produit : logo, typo, couleurs, chaque écran dans Figma, puis le développement SvelteKit.\"}"}', '2026-09-28 15:55:20.378', '2026-09-29 10:42:04.174', '[]');
