INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('a751dfbf-4f35-4b49-a978-5d67d77d78e7', 'marcel', 0, NULL, '{}', NULL);
INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('1c1dfd34-e587-42b3-a9d4-3663e0717c7e', 'marcel', 1, '{"de": "Neues Gesicht!", "en": "New Face!", "es": "¡Nueva cara!", "fr": "Nouveau visage !"}', '{camille}', '{"cols": 8, "items": [{"h": 1, "w": 2, "x": 1, "y": 1, "id": "b0-0", "kind": "note", "text": {"de": "Marcel war etwas in die Jahre gekommen. Also bat er uns freundlich, ihn aufzufrischen und ihm das Gesicht und den Glanz zu geben, die er brauchte. Die Idee für dieses Rebranding stammt von Camille.", "en": "Marcel started to get a bit old. So he kindly asked us to revamp him and give him the face and shine he needed. The ideation of this rebranding was made by Camille.", "es": "Marcel empezaba a hacerse mayor. Así que nos pidió amablemente un lavado de cara que le devolviera el brillo que necesitaba. La idea de este rebranding fue de Camille.", "fr": "Marcel commençait à prendre un coup de vieux. Il nous a donc gentiment demandé de le rafraîchir et de lui offrir le visage et l''éclat qu''il méritait. L''idée de ce rebranding vient de Camille."}, "title": {"de": "Neues Gesicht!", "en": "New Face!", "es": "¡Nueva cara!", "fr": "Nouveau visage !"}}, {"h": 2, "w": 2, "x": 1, "y": 2, "id": "b0-1", "src": "/images/projects/Marcel%202x2%20logo.png", "kind": "image"}, {"h": 3, "w": 2, "x": 3, "y": 1, "id": "b1-0", "src": "/images/projects/Marcel%202x3%20rebranding.png", "kind": "image"}, {"h": 3, "w": 2, "x": 7, "y": 1, "id": "b2-0", "kind": "palette", "swatches": [{"hex": "#F9F1E7", "label": {"de": "Hintergrund", "en": "Background", "es": "Fondo", "fr": "Fond"}}, {"hex": "#E2DAD2", "note": {"de": "#F9F1E7 + #0E0F10 (Deckkraft 10 %)", "en": "#F9F1E7 + #0E0F10 (opacity 10%)", "es": "#F9F1E7 + #0E0F10 (opacidad 10 %)", "fr": "#F9F1E7 + #0E0F10 (opacité 10 %)"}, "label": {"de": "Komponentenfläche", "en": "Component Bg", "es": "Fondo componente", "fr": "Fond composant"}}, {"hex": "#494846", "note": {"de": "#0E0F10 (Deckkraft 75 %)", "en": "#0E0F10 (opacity 75%)", "es": "#0E0F10 (opacidad 75 %)", "fr": "#0E0F10 (opacité 75 %)"}, "label": {"de": "Nebentext", "en": "Subtext", "es": "Subtexto", "fr": "Sous-texte"}}, {"hex": "#0E0F10", "label": {"de": "Text", "en": "Text", "es": "Texto", "fr": "Texte"}}]}, {"h": 3, "w": 2, "x": 5, "y": 1, "id": "b3-0", "font": "Poppins", "kind": "typography", "fontFamily": "var(--font-poppins), sans-serif", "description": {"de": "PLACEHOLDER: erklären, warum Poppins gewählt wurde, welche Rolle sie in Titeln und Fließtext spielt und wie ihre runde, freundliche Geometrie zu Marcels Ton passt.", "en": "PLACEHOLDER — explain why Poppins was chosen: its role across titles, body copy and where its rounded, friendly geometry fits Marcel''s tone.", "es": "PLACEHOLDER: explicar por qué se eligió Poppins, su papel en títulos y texto, y cómo su geometría redondeada y amable encaja con el tono de Marcel.", "fr": "Poppins est une typographie ronde et harmonieuse qui met en valeur Marcel sans prendre trop de place. Elle rajoute un sentiment de calme et bonté qui aide grandement l''application a se fait sentir chez soi."}, "secondDescription": {"de": "", "en": "", "es": "", "fr": ""}}]}');
INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('9ea2a431-b2c9-49fe-908d-a2b03a901f6a', 'benky', 1, '{"de": "Lernsession", "en": "Study session", "es": "Sesión de estudio", "fr": "Session de révision"}', '{fanga}', '{"cols": 5, "items": [{"h": 1, "w": 2, "x": 1, "y": 1, "id": "b0-0", "kind": "note", "text": {"de": "Eine Session hat drei Schritte: PDFs, Bilder und Notizen nach Fach sammeln, Benky fragen, bis die Idee sitzt, und dann mit Karteikarten, Quiz und einem Termin im Wochenkalender darauf zurückkommen.", "en": "A session runs in three steps: gather PDFs, images and notes by subject, ask Benky until the idea makes sense, then come back to it with flashcards, quizzes and a slot on the weekly calendar.", "es": "Una sesión sigue tres pasos: reunir PDF, imágenes y apuntes por asignatura, preguntar a Benky hasta que la idea quede clara y volver a ella con flashcards, cuestionarios y un hueco en el calendario semanal.", "fr": "Une session se déroule en trois étapes : rassembler PDF, images et notes par matière, questionner Benky jusqu''à ce que l''idée soit claire, puis y revenir avec des flashcards, des quiz et un créneau dans le calendrier de la semaine."}, "title": {"de": "Lernsession", "en": "Study session", "es": "Sesión de estudio", "fr": "Session de révision"}}, {"h": 3, "w": 3, "x": 3, "y": 1, "id": "1dce6f6a-9704-4c54-b3fc-6e1c121efb66", "src": "/images/projects/uploads/1790683845983-benky-demo.mp4", "kind": "video"}]}');
