INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('2f23ec83-f5a3-49d3-8e02-e37a4ae3e28b', 'handvision', 0, NULL, '{}', '{"cols": 5, "items": [{"h": 3, "w": 3, "x": 1, "y": 1, "id": "b0-0", "kind": "cover"}, {"h": 3, "w": 2, "x": 4, "y": 1, "id": "b1-0", "kind": "intro"}]}');
INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('5b89e4db-5ab5-4f6c-827f-e0815c9e3779', 'handvision', 1, '{"de": "So funktioniert es", "en": "How it works", "es": "Cómo funciona", "fr": "Comment ça marche"}', '{noah}', '{"cols": 5, "items": [{"h": 3, "w": 3, "x": 3, "y": 1, "id": "0998fee7-c05d-4c8a-9435-f71d8c977fae", "src": "/images/projects/uploads/1790619288788-Marcel-3x3-dashboard.png", "kind": "image"}, {"h": 1, "w": 2, "x": 1, "y": 1, "id": "b0-0", "kind": "note", "text": {"de": "Drei Schritte, kein manuelles Taggen. Der Trainer lädt das Spielvideo hoch, ein auf Handball trainiertes Erkennungsmodell markiert jedes Tor mit Timecode, dann springt der Trainer von Clip zu Clip und liest Spieler- und Teamstatistiken aus dem Spielbericht, alles auf einer Seite.", "en": "Three steps, no manual tagging. The coach uploads the match video, a detection model trained on handball marks every goal with its timecode, then the coach jumps from clip to clip and reads player and team statistics from the match sheet, all on one page.", "es": "Tres pasos, sin etiquetar nada a mano. El entrenador sube el vídeo del partido, un modelo de detección entrenado con balonmano marca cada gol con su timecode, y después el entrenador salta de clip en clip y lee las estadísticas de jugadores y equipo sacadas del acta, todo en una sola página.", "fr": "Le coach upload une vidéo d''un match filmé avec son téléphone, puis notre IA la sépare en séquences attaque/défense. Le coach peut alors lire chaques actions une par une et se repérer dans des vidéos qui durent parfois des heures facilement."}, "title": {"de": "So funktioniert es", "en": "How it works", "es": "Cómo funciona", "fr": "Qu''est ce qu''Handvision"}}, {"h": 2, "w": 2, "x": 1, "y": 2, "id": "5a3ed6f8-95ed-40d8-b4b3-14032bbfaec1", "src": "/images/projects/uploads/1790621780452-Marcel-3x3-dashboard.png", "kind": "image"}]}');
INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('b55fe6bd-d393-43e5-af8c-679972f83c68', 'handvision', 2, '{"de": "Branding", "en": "Branding", "es": "Identidad", "fr": "Identité"}', '{noah}', '{"cols": 9, "items": [{"h": 1, "w": 2, "x": 1, "y": 1, "id": "b0-0", "kind": "note", "text": {"de": "Noah hat das Logo gezeichnet, die Schrift gewählt und die Farben festgelegt. Ein tiefes Schwarz lässt das Spielmaterial das Hellste auf dem Bildschirm bleiben, und ein einziger violetter Verlauf markiert alles, was die KI für dich erledigt.", "en": "Noah drew the logo, picked the font and set the colours. A deep black lets match footage stay the brightest thing on screen, and a single violet gradient marks everything the AI does for you.", "es": "Noah dibujó el logo, eligió la tipografía y definió los colores. Un negro profundo deja que las imágenes del partido sean lo más brillante de la pantalla, y un único degradado violeta marca todo lo que la IA hace por ti.", "fr": "Noah a fait une refonte de l''UI de HandVision ainsi que son univers graphique. Utilisant des couleurs vives et des contrastes forts, il est parvenu a rendre son mémoire encore plus intéressant."}, "title": {"de": "Branding", "en": "Branding", "es": "Identidad", "fr": "Identité"}}, {"h": 2, "w": 2, "x": 1, "y": 2, "id": "b37e2097-05c1-445a-8420-bb55d8277fea", "src": "/images/projects/uploads/1790619277805-2x2.png", "kind": "image"}, {"h": 3, "w": 2, "x": 3, "y": 1, "id": "57976fb7-d666-41ba-b1e8-631e2b3542d0", "src": "/images/projects/uploads/1790621273024-2x3.png", "kind": "image"}, {"h": 3, "w": 2, "x": 5, "y": 1, "id": "b1-0", "kind": "palette", "swatches": [{"hex": "#0A0A0A", "label": {"de": "Hintergrund", "en": "Background", "es": "Fondo", "fr": "Fond"}}, {"hex": "#161616", "note": {"de": "#FFFFFF (Deckkraft 5 %)", "en": "#FFFFFF (opacity 5%)", "es": "#FFFFFF (opacidad 5 %)", "fr": "#FFFFFF (opacité 5 %)"}, "label": {"de": "Komponente", "en": "Component", "es": "Componente", "fr": "Composant"}}, {"hex": "linear-gradient(30deg, #6354E0 0%, #B12DDD 100%)", "hsv": "—", "rgb": "—", "cmyk": "—", "note": {"de": "Verlauf: #6354E0 → #B12DDD", "en": "Gradient: #6354E0 → #B12DDD", "es": "Degradado: #6354E0 → #B12DDD", "fr": "Dégradé : #6354E0 → #B12DDD"}, "label": {"de": "Verlauf", "en": "Gradient", "es": "Degradado", "fr": "Dégradé"}, "textColor": "#FFFFFF"}, {"hex": "#FFFFFF", "label": {"de": "Text", "en": "Text", "es": "Texto", "fr": "Texte"}}, {"hex": "#858585", "note": {"de": "#FFFFFF (Deckkraft 50 %)", "en": "#FFFFFF (opacity 50%)", "es": "#FFFFFF (opacidad 50 %)", "fr": "#FFFFFF (opacité 50 %)"}, "label": {"de": "Nebentext", "en": "Subtext", "es": "Subtexto", "fr": "Sous-texte"}}]}, {"h": 3, "w": 3, "x": 7, "y": 1, "id": "2bf6fb90-218c-41ec-8f60-2c5445ab1ce6", "src": "/images/projects/uploads/1790621278559-Marcel-3x3-dashboard.png", "kind": "image"}]}');
INSERT INTO "StorySection" (id, "projectSlug", "position", title, by, layout) VALUES ('4b24d5cb-0a08-4315-9bf8-97989bc31305', 'handvision', 3, '{"de": "Webdesign", "en": "Web Design", "es": "Diseño web", "fr": "Web design"}', '{noah}', '{"cols": 5, "items": [{"h": 1, "w": 2, "x": 1, "y": 1, "id": "b0-0", "kind": "note", "text": {"de": "Noah hat jeden Screen in Figma entworfen: die Landing, die Seiten für Analyse, Statistiken und Preise und danach die App selbst. Die Landing zeigt das Produkt, statt es zu beschreiben, mit einem Bento aus lebendig wirkenden Visuals für Erkennung, Clips, Statistiken und Credits.", "en": "Noah designed every screen in Figma: the landing, the analysis, statistics and pricing pages, then the app itself. The landing shows the product instead of describing it, with a bento of live-looking visuals for detection, clips, stats and credits.", "es": "Noah diseñó cada pantalla en Figma: la landing, las páginas de análisis, estadísticas y precios, y después la propia aplicación. La landing muestra el producto en lugar de describirlo, con un bento de visuales que parecen en vivo para la detección, los clips, las estadísticas y los créditos.", "fr": "Grâce aux personnes avec qui Noah a pu travaillé, Hanvision permet aussi de lire une feuille de match pour récupérer automatiquement toutes les statistiques du match pris en vidéo."}, "title": {"de": "Webdesign", "en": "Web Design", "es": "Diseño web", "fr": "Technicité"}}, {"h": 3, "w": 3, "x": 3, "y": 1, "id": "f2dd267c-9da7-4992-b87e-3bcf163f63dd", "src": "/images/projects/uploads/1790621533101-Marcel-3x3-dashboard-1.png", "kind": "image"}, {"h": 2, "w": 1, "x": 1, "y": 2, "id": "1f361722-c669-41bb-a865-5df6133dd9dd", "src": "/images/projects/uploads/1790619298031-1x2.png", "kind": "image"}, {"h": 2, "w": 1, "x": 2, "y": 2, "id": "2c326e71-d987-4dc3-a0d4-773e44df4718", "src": "/images/projects/uploads/1790623476437-1x2.png", "kind": "image"}]}');
