INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('5069e6c3-6eab-439d-b928-f98285b0e7ae', '38c2e7da-e300-4fd1-8aff-a652c62f41d7', 0, 'note', '[0]', NULL, '{"de": "Ideenfindung", "en": "Ideation", "es": "Ideación", "fr": "Idéation"}', '{"de": "Ausgangspunkt war weder ein Soldat noch ein Raumschiff, sondern die Energie selbst: ein Zeichen, das zuerst wie geborgene Alien-Technik wirkt und erst dann wie ein Spielelogo.", "en": "The starting point wasn''t a soldier or a spaceship, it was the energy itself: a mark that reads as scavenged alien tech first, game logo second.", "es": "El punto de partida no fue un soldado ni una nave, sino la propia energía: una marca que se lee primero como tecnología alienígena rescatada y después como logo de juego.", "fr": "Le point de départ n''était ni un soldat ni un vaisseau, mais l''énergie elle-même : un signe qui se lit d''abord comme une techno extraterrestre récupérée, ensuite comme un logo de jeu."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('13cc52cb-9ea3-48fa-a7ba-c556327491c8', '38c2e7da-e300-4fd1-8aff-a652c62f41d7', 1, 'big', '[1, 2, 3]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'top', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('26801834-1bf9-49a1-be6d-5ec7bfa31227', '38c2e7da-e300-4fd1-8aff-a652c62f41d7', 2, 'collage', '[12, 13, 14, 15]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('c111cf28-4d31-465c-86a6-8a64b246bdc3', 'bf89a557-498f-46d8-8b96-7c1b7d24f61e', 0, 'note', '[4]', NULL, '{"de": "Styleguide", "en": "Graphic Chart", "es": "Guía gráfica", "fr": "Charte graphique"}', '{"de": "Jede Fläche, ob Website, Shop, Battle Pass oder Marketing, schöpft aus demselben Blau der uralten Energie. So bleibt die Welt immer in ihrer Rolle, vom Screenshot bis zum Instagram-Post.", "en": "Every surface — site, shop, battle pass, marketing — draws from the same ancient-energy blue, so the world never breaks character switching from screenshot to Instagram post.", "es": "Cada superficie, desde la web y la tienda hasta el pase de batalla y el marketing, bebe del mismo azul de energía ancestral, así que el mundo nunca rompe el personaje al pasar de una captura a un post de Instagram.", "fr": "Chaque support, du site à la boutique en passant par le battle pass et le marketing, puise dans le même bleu d''énergie ancestrale : l''univers ne sort jamais de son rôle, d''une capture d''écran à un post Instagram."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('1b5d966a-2a4b-40ac-ab72-6a4743b8ba15', 'bf89a557-498f-46d8-8b96-7c1b7d24f61e', 1, 'palette', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"hex": "#121219", "label": {"de": "Hintergrund", "en": "Background", "es": "Fondo", "fr": "Fond"}}, {"hex": "#181920", "note": {"de": "#E8EEFF (Deckkraft 3 %), Infos und Titel", "en": "#E8EEFF (opacity 3%) — informations & titles", "es": "#E8EEFF (opacidad 3 %), información y títulos", "fr": "#E8EEFF (opacité 3 %), informations et titres"}, "label": {"de": "Komponente", "en": "Component", "es": "Componente", "fr": "Composant"}}, {"hex": "linear-gradient(135deg, #B4C3F0 0%, #7B8FD6 100%)", "hsv": "—", "rgb": "—", "cmyk": "—", "note": {"de": "Verlauf: #B4C3F0 → #7B8FD6", "en": "Gradient: #B4C3F0 → #7B8FD6", "es": "Degradado: #B4C3F0 → #7B8FD6", "fr": "Dégradé : #B4C3F0 → #7B8FD6"}, "label": {"de": "H1-Titel Verlauf", "en": "H1 Title Gradient", "es": "Título H1 degradado", "fr": "Titre H1 Dégradé"}, "textColor": "#0E0F10"}, {"hex": "#E8EEFF", "label": {"de": "Text", "en": "Text", "es": "Texto", "fr": "Texte"}}, {"hex": "#7D808C", "note": {"de": "#E8EEFF (Deckkraft 50 %), Nebeninfos", "en": "#E8EEFF (opacity 50%) — minor informations", "es": "#E8EEFF (opacidad 50 %), información secundaria", "fr": "#E8EEFF (opacité 50 %), informations secondaires"}, "label": {"de": "Nebentext", "en": "Subtext", "es": "Subtexto", "fr": "Sous-texte"}}]');
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('ae5e7daa-5937-46ef-87f1-0d6c384af394', 'bf89a557-498f-46d8-8b96-7c1b7d24f61e', 2, 'typographyPair', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'DM Sans', 'var(--font-dm-sans), sans-serif', '{"de": "PLACEHOLDER: erklären, warum DM Sans die Titel trägt, ihr geometrisches Gewicht vor dem tiefschwarzen Hintergrund und warum sie in großen Größen wie „Alien-Technik“ wirkt.", "en": "PLACEHOLDER — explain why DM Sans carries the titles: its geometric weight against the void-black background, and how it reads as \"alien tech\" at large sizes.", "es": "PLACEHOLDER: explicar por qué DM Sans lleva los títulos, su peso geométrico sobre el fondo negro vacío y cómo se lee como \"tecnología alienígena\" en tamaños grandes.", "fr": "PLACEHOLDER : expliquer pourquoi DM Sans porte les titres, son poids géométrique sur le fond noir abyssal, et comment elle évoque une « techno extraterrestre » en grande taille."}', 'IBM Plex Mono', 'var(--font-ibm-plex-mono), monospace', '{"de": "PLACEHOLDER: erklären, warum IBM Plex Mono den Fließtext trägt, und welches Terminal-/HUD-Gefühl sie Stats, Kapiteltexten und UI-Labels gibt.", "en": "PLACEHOLDER — explain why IBM Plex Mono carries body text: the terminal/HUD feel it gives to stats, chapter copy and UI labels.", "es": "PLACEHOLDER: explicar por qué IBM Plex Mono lleva el texto, y el aire de terminal/HUD que da a las estadísticas, los textos de capítulo y las etiquetas de la interfaz.", "fr": "PLACEHOLDER : expliquer pourquoi IBM Plex Mono porte le texte courant, et l''effet terminal/HUD qu''elle donne aux stats, aux textes de chapitre et aux libellés d''interface."}', NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('be4b6e8a-790f-4982-9fec-9d9cd3a1ba84', 'bf89a557-498f-46d8-8b96-7c1b7d24f61e', 3, 'full', '[5]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('7aba5128-0825-42fe-8e89-bba9b19091a5', '4f4f8050-ae15-4633-aca0-08ff7a9a5b61', 0, 'note', '[6]', NULL, '{"de": "Webdesign", "en": "Web Design", "es": "Diseño web", "fr": "Web design"}', '{"de": "Showcase-Website, Shop und Infoseite zu den Kapiteln (Battle Pass), gebaut als ein einziges Kontinuum: Dasselbe blaue Leuchten wird stärker, je weiter man von der Lore zur Beute kommt.", "en": "Showcase site, shop and chapter (battle pass) info page, all built as one continuum — the same blue glow escalates as you move from lore to loot.", "es": "Web de presentación, tienda y página de información de capítulos (pase de batalla), todo construido como un único continuo: el mismo brillo azul se intensifica a medida que pasas del lore al botín.", "fr": "Site vitrine, boutique et page d''infos des chapitres (battle pass), pensés comme un seul continuum : la même lueur bleue monte en intensité à mesure qu''on passe du lore au butin."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('75b1a2d2-e60b-42e7-a7e2-fb4c43fc7a55', '4f4f8050-ae15-4633-aca0-08ff7a9a5b61', 1, 'mosaic', '[7, 8, 9, 10, 11]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
