INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('3ec7370c-1ced-414a-956d-352008f90c87', 'a751dfbf-4f35-4b49-a978-5d67d77d78e7', 1, 'intro', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('92a630d8-e477-486f-b91b-4f63f52f6290', '1c1dfd34-e587-42b3-a9d4-3663e0717c7e', 0, 'note', '[0]', NULL, '{"de": "Neues Gesicht!", "en": "New Face!", "es": "¡Nueva cara!", "fr": "Nouveau visage !"}', '{"de": "Marcel war etwas in die Jahre gekommen. Also bat er uns freundlich, ihn aufzufrischen und ihm das Gesicht und den Glanz zu geben, die er brauchte. Die Idee für dieses Rebranding stammt von Camille.", "en": "Marcel started to get a bit old. So he kindly asked us to revamp him and give him the face and shine he needed. The ideation of this rebranding was made by Camille.", "es": "Marcel empezaba a hacerse mayor. Así que nos pidió amablemente un lavado de cara que le devolviera el brillo que necesitaba. La idea de este rebranding fue de Camille.", "fr": "Marcel commençait à prendre un coup de vieux. Il nous a donc gentiment demandé de le rafraîchir et de lui offrir le visage et l''éclat qu''il méritait. L''idée de ce rebranding vient de Camille."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('87fbe403-65cf-48f6-b970-c8805dd01c7a', '1c1dfd34-e587-42b3-a9d4-3663e0717c7e', 1, 'full', '[1]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('71adaa22-01ce-465c-8300-1ddeb1e09770', '1c1dfd34-e587-42b3-a9d4-3663e0717c7e', 2, 'palette', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"hex": "#F9F1E7", "label": {"de": "Hintergrund", "en": "Background", "es": "Fondo", "fr": "Fond"}}, {"hex": "#E2DAD2", "note": {"de": "#F9F1E7 + #0E0F10 (Deckkraft 10 %)", "en": "#F9F1E7 + #0E0F10 (opacity 10%)", "es": "#F9F1E7 + #0E0F10 (opacidad 10 %)", "fr": "#F9F1E7 + #0E0F10 (opacité 10 %)"}, "label": {"de": "Komponentenfläche", "en": "Component Bg", "es": "Fondo componente", "fr": "Fond composant"}}, {"hex": "#494846", "note": {"de": "#0E0F10 (Deckkraft 75 %)", "en": "#0E0F10 (opacity 75%)", "es": "#0E0F10 (opacidad 75 %)", "fr": "#0E0F10 (opacité 75 %)"}, "label": {"de": "Nebentext", "en": "Subtext", "es": "Subtexto", "fr": "Sous-texte"}}, {"hex": "#0E0F10", "label": {"de": "Text", "en": "Text", "es": "Texto", "fr": "Texte"}}]');
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('98f20dcf-c285-442f-8d8e-c7f30ae53302', '1c1dfd34-e587-42b3-a9d4-3663e0717c7e', 3, 'typography', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Poppins', 'var(--font-poppins), sans-serif', '{"de": "PLACEHOLDER: erklären, warum Poppins gewählt wurde, welche Rolle sie in Titeln und Fließtext spielt und wie ihre runde, freundliche Geometrie zu Marcels Ton passt.", "en": "PLACEHOLDER — explain why Poppins was chosen: its role across titles, body copy and where its rounded, friendly geometry fits Marcel''s tone.", "es": "PLACEHOLDER: explicar por qué se eligió Poppins, su papel en títulos y texto, y cómo su geometría redondeada y amable encaja con el tono de Marcel.", "fr": "PLACEHOLDER : expliquer pourquoi Poppins a été choisie, son rôle dans les titres et le texte courant, et en quoi sa géométrie ronde et amicale colle au ton de Marcel."}', NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('d8f1b1dd-91a4-4587-aeff-025b568d9c7f', '65af0fa4-7f43-494f-a875-9bb84f4289d0', 0, 'note', '[2]', NULL, '{"de": "Redesign", "en": "Redesign", "es": "Rediseño", "fr": "Refonte"}', '{"de": "Auf Basis des Styleguides haben Noah und Camille die gesamte Marcel-App neu gestaltet. Mit viel Sorgfalt für jede Komponente haben wir einer müden Website neues Leben eingehaucht.", "en": "Based on the graphical chart, Noah and Camille teamed up to redesign the entire Marcel app. By carefully crafting every component, we gave a new life to a tired website.", "es": "Partiendo de la guía gráfica, Noah y Camille unieron fuerzas para rediseñar toda la app de Marcel. Cuidando cada componente, le dimos una nueva vida a una web cansada.", "fr": "À partir de la charte graphique, Noah et Camille ont uni leurs forces pour refondre toute l''application Marcel. En soignant chaque composant, nous avons donné une nouvelle vie à un site fatigué."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('420e30e1-cd0b-46b3-9d8b-a5113f9b9296', '65af0fa4-7f43-494f-a875-9bb84f4289d0', 1, 'collage', '[4, 5, 3, 6]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('d1db60ad-d171-4f4b-86cf-52db1a691aaf', 'e69fa49e-f2bb-434d-b871-d068138e1a41', 0, 'note', '[13]', NULL, '{"de": "Umsetzung", "en": "Implementation", "es": "Implementación", "fr": "Développement"}', '{"de": "Jetzt müssen wir nur noch die Zeit finden, Marcel seine neue Identität tatsächlich zu geben. Das dauert noch etwas, aber wir kommen ans Ziel! ;)", "en": "Now we just have to find the time to actually give Marcel its newly created identity. It will take a moment but we will eventually get there! ;)", "es": "Ahora solo nos falta encontrar tiempo para darle a Marcel su nueva identidad. Llevará un rato, ¡pero lo conseguiremos! ;)", "fr": "Il ne nous reste plus qu''à trouver le temps de donner à Marcel sa toute nouvelle identité. Ça prendra un moment, mais on y arrivera ! ;)"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
