INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('a27bdfe0-e235-4483-b306-2b620a16c446', '5b89e4db-5ab5-4f6c-827f-e0815c9e3779', 0, 'note', '[0]', NULL, '{"de": "So funktioniert es", "en": "How it works", "es": "Cómo funciona", "fr": "Comment ça marche"}', '{"de": "Drei Schritte, kein manuelles Taggen. Der Trainer lädt das Spielvideo hoch, ein auf Handball trainiertes Erkennungsmodell markiert jedes Tor mit Timecode, dann springt der Trainer von Clip zu Clip und liest Spieler- und Teamstatistiken aus dem Spielbericht, alles auf einer Seite.", "en": "Three steps, no manual tagging. The coach uploads the match video, a detection model trained on handball marks every goal with its timecode, then the coach jumps from clip to clip and reads player and team statistics from the match sheet, all on one page.", "es": "Tres pasos, sin etiquetar nada a mano. El entrenador sube el vídeo del partido, un modelo de detección entrenado con balonmano marca cada gol con su timecode, y después el entrenador salta de clip en clip y lee las estadísticas de jugadores y equipo sacadas del acta, todo en una sola página.", "fr": "Trois étapes, aucun marquage à la main. Le coach envoie la vidéo du match, un modèle de détection entraîné sur le handball repère chaque but avec son timecode, puis le coach passe d''un clip à l''autre et lit les statistiques des joueurs et de l''équipe tirées de la feuille de match, le tout sur une seule page."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('2d0a7f88-5d8c-47c3-939a-0c66e00321f9', '5b89e4db-5ab5-4f6c-827f-e0815c9e3779', 1, 'big', '[3, 1, 2]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'top', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('b157f78d-f281-4f68-a16d-5713bdac7d66', 'b55fe6bd-d393-43e5-af8c-679972f83c68', 0, 'note', '[4]', NULL, '{"de": "Branding", "en": "Branding", "es": "Identidad", "fr": "Identité"}', '{"de": "Noah hat das Logo gezeichnet, die Schrift gewählt und die Farben festgelegt. Ein tiefes Schwarz lässt das Spielmaterial das Hellste auf dem Bildschirm bleiben, und ein einziger violetter Verlauf markiert alles, was die KI für dich erledigt.", "en": "Noah drew the logo, picked the font and set the colours. A deep black lets match footage stay the brightest thing on screen, and a single violet gradient marks everything the AI does for you.", "es": "Noah dibujó el logo, eligió la tipografía y definió los colores. Un negro profundo deja que las imágenes del partido sean lo más brillante de la pantalla, y un único degradado violeta marca todo lo que la IA hace por ti.", "fr": "Noah a dessiné le logo, choisi la typo et fixé les couleurs. Un noir profond laisse les images du match rester l''élément le plus lumineux de l''écran, et un seul dégradé violet signale tout ce que l''IA fait pour vous."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('0ee9643d-5bad-41fe-8faf-746973bfba42', 'b55fe6bd-d393-43e5-af8c-679972f83c68', 1, 'palette', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"hex": "#0A0A0A", "label": {"de": "Hintergrund", "en": "Background", "es": "Fondo", "fr": "Fond"}}, {"hex": "#161616", "note": {"de": "#FFFFFF (Deckkraft 5 %)", "en": "#FFFFFF (opacity 5%)", "es": "#FFFFFF (opacidad 5 %)", "fr": "#FFFFFF (opacité 5 %)"}, "label": {"de": "Komponente", "en": "Component", "es": "Componente", "fr": "Composant"}}, {"hex": "linear-gradient(30deg, #6354E0 0%, #B12DDD 100%)", "hsv": "—", "rgb": "—", "cmyk": "—", "note": {"de": "Verlauf: #6354E0 → #B12DDD", "en": "Gradient: #6354E0 → #B12DDD", "es": "Degradado: #6354E0 → #B12DDD", "fr": "Dégradé : #6354E0 → #B12DDD"}, "label": {"de": "Verlauf", "en": "Gradient", "es": "Degradado", "fr": "Dégradé"}, "textColor": "#FFFFFF"}, {"hex": "#FFFFFF", "label": {"de": "Text", "en": "Text", "es": "Texto", "fr": "Texte"}}, {"hex": "#858585", "note": {"de": "#FFFFFF (Deckkraft 50 %)", "en": "#FFFFFF (opacity 50%)", "es": "#FFFFFF (opacidad 50 %)", "fr": "#FFFFFF (opacité 50 %)"}, "label": {"de": "Nebentext", "en": "Subtext", "es": "Subtexto", "fr": "Sous-texte"}}]');
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('aead4c87-8ca9-4f5e-8a36-edb42e1b1e3f', 'b55fe6bd-d393-43e5-af8c-679972f83c68', 2, 'typography', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SF Pro Display', '''SF Pro Display'', -apple-system, sans-serif', '{"de": "PLACEHOLDER: erklären, warum SF Pro Display gewählt wurde, eine neutrale, sportliche Grotesk, die in dichten Statistiktabellen lesbar bleibt und auch in großen Landing-Titeln trägt.", "en": "PLACEHOLDER — explain why SF Pro Display was chosen: a neutral, sporty sans that stays readable in dense stat tables and still holds up in big landing titles.", "es": "PLACEHOLDER: explicar por qué se eligió SF Pro Display, una sans neutra y deportiva que sigue siendo legible en tablas de estadísticas densas y aguanta bien en los grandes títulos de la landing.", "fr": "PLACEHOLDER : expliquer pourquoi SF Pro Display a été choisie, une linéale neutre et sportive qui reste lisible dans les tableaux de stats denses et tient la route dans les grands titres de la landing."}', NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('e4a0851f-3918-4143-8256-5a1cf6280218', 'b55fe6bd-d393-43e5-af8c-679972f83c68', 3, 'full', '[5]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('eb42f3a6-ef96-4078-af04-4e1360e85d0e', '4b24d5cb-0a08-4315-9bf8-97989bc31305', 0, 'note', '[6]', NULL, '{"de": "Webdesign", "en": "Web Design", "es": "Diseño web", "fr": "Web design"}', '{"de": "Noah hat jeden Screen in Figma entworfen: die Landing, die Seiten für Analyse, Statistiken und Preise und danach die App selbst. Die Landing zeigt das Produkt, statt es zu beschreiben, mit einem Bento aus lebendig wirkenden Visuals für Erkennung, Clips, Statistiken und Credits.", "en": "Noah designed every screen in Figma: the landing, the analysis, statistics and pricing pages, then the app itself. The landing shows the product instead of describing it, with a bento of live-looking visuals for detection, clips, stats and credits.", "es": "Noah diseñó cada pantalla en Figma: la landing, las páginas de análisis, estadísticas y precios, y después la propia aplicación. La landing muestra el producto en lugar de describirlo, con un bento de visuales que parecen en vivo para la detección, los clips, las estadísticas y los créditos.", "fr": "Noah a conçu chaque écran dans Figma : la landing, les pages analyse, statistiques et tarifs, puis l''application elle-même. La landing montre le produit au lieu de le décrire, avec un bento de visuels qui semblent vivants pour la détection, les clips, les stats et les crédits."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
