INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('a2a78018-3a43-4041-987e-088459389487', '00a7b748-cb91-4ecc-bb3e-5b4f8cc86c05', 0, 'note', '[0]', NULL, '{"de": "Art Direction", "en": "Art direction", "es": "Dirección de arte", "fr": "Direction artistique"}', '{"de": "Hier trägt die Bewegung den gesamten redaktionellen Rhythmus: Nichts bewegt sich, ohne sich den Blick des Betrachters zu verdienen.", "en": "Motion carries the whole editorial rhythm here — nothing moves unless it earns the reader''s eye.", "es": "Aquí el movimiento marca todo el ritmo editorial: nada se mueve si no merece la mirada de quien lee.", "fr": "Ici, le mouvement porte tout le rythme éditorial : rien ne bouge sans mériter le regard du lecteur."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
