INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('3ad6c7da-4771-4efc-a89d-d688b0faf5cc', '3765b28d-b65c-4967-979a-20f4fd711a92', 0, 'note', '[0]', NULL, '{"de": "Art Direction", "en": "Art direction", "es": "Dirección de arte", "fr": "Direction artistique"}', '{"de": "Die Wärme kommt von der Palette und dem Tempo, nicht von Dekoration: Das Layout bleibt bewusst fast leer.", "en": "Warmth came from the palette and the pacing, not from decoration — the layout stays almost bare on purpose.", "es": "La calidez viene de la paleta y del ritmo, no de la decoración: la maquetación se queda casi desnuda a propósito.", "fr": "La chaleur vient de la palette et du rythme, pas de la décoration : la mise en page reste volontairement presque nue."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
