INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('a4319372-616c-46fc-a97c-dc8a347ae872', '66df457a-0411-4a16-ad2d-59215a322c2a', 0, 'note', '[0]', NULL, '{"de": "Produktdesign", "en": "Product design", "es": "Diseño de producto", "fr": "Design produit"}', '{"de": "Mazouz hat Vidoq um drei Werkzeuge gebaut: eine Leak-Suche über sechs Identifikatoren, einen Graphen, der Datensätze gruppiert und gleiche Felder quellenübergreifend verknüpft, und passive Benachrichtigungen, wenn ein überwachtes Feld in einem neuen Leak auftaucht.", "en": "Mazouz built Vidoq around three tools: a breach search on six identifiers, a graph that groups leaked records and links matching fields across sources, and passive alerts when a watched field appears in a new breach.", "es": "Mazouz construyó Vidoq en torno a tres herramientas: una búsqueda de filtraciones sobre seis identificadores, un grafo que agrupa los registros y enlaza los campos coincidentes entre fuentes, y alertas pasivas cuando un campo vigilado aparece en una nueva filtración.", "fr": "Mazouz a construit Vidoq autour de trois outils : une recherche de fuites sur six identifiants, un graphe qui regroupe les enregistrements et relie les champs identiques entre les sources, et des alertes passives quand un champ surveillé apparaît dans une nouvelle fuite."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
