INSERT INTO "StoryBlock" (id, "sectionId", "position", type, media, eyebrow, title, text, tags, logos, tiles, link, "linkLabel", effect, smalls, cols, font, "fontFamily", description, "secondFont", "secondFontFamily", "secondDescription", swatches) VALUES ('d3f0f604-903e-44b0-9a8b-98ef93c26fd1', '9ea2a431-b2c9-49fe-908d-a2b03a901f6a', 0, 'note', '[0]', NULL, '{"de": "Lernsession", "en": "Study session", "es": "Sesión de estudio", "fr": "Session de révision"}', '{"de": "Eine Session hat drei Schritte: PDFs, Bilder und Notizen nach Fach sammeln, Benky fragen, bis die Idee sitzt, und dann mit Karteikarten, Quiz und einem Termin im Wochenkalender darauf zurückkommen.", "en": "A session runs in three steps: gather PDFs, images and notes by subject, ask Benky until the idea makes sense, then come back to it with flashcards, quizzes and a slot on the weekly calendar.", "es": "Una sesión sigue tres pasos: reunir PDF, imágenes y apuntes por asignatura, preguntar a Benky hasta que la idea quede clara y volver a ella con flashcards, cuestionarios y un hueco en el calendario semanal.", "fr": "Une session se déroule en trois étapes : rassembler PDF, images et notes par matière, questionner Benky jusqu''à ce que l''idée soit claire, puis y revenir avec des flashcards, des quiz et un créneau dans le calendrier de la semaine."}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
